.version 7.0
.target sm_80
.address_size 64

.visible .entry swish_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 N
)
{
    .reg .pred   %p;
    .reg .u32    %tid, %bid, %bdim, %grid_dim;
    .reg .u64    %tid64, %bid64, %bdim64, %grid_dim64;
    .reg .u64    %global_id, %total_threads;
    .reg .u64    %i, %offset;
    .reg .f16    %x_h, %y_h;
    .reg .f32    %x_f, %x_orig, %neg_x, %exp_val, %denom, %sig_f, %y_f;

    // thread identifiers
    mov.u32      %tid,      %tid.x;
    mov.u32      %bid,      %ctaid.x;
    mov.u32      %bdim,     %ntid.x;
    mov.u32      %grid_dim, %nctaid.x;

    // widen to 64‑bit
    cvt.u64.u32  %tid64,    %tid;
    cvt.u64.u32  %bid64,    %bid;
    cvt.u64.u32  %bdim64,   %bdim;
    cvt.u64.u32  %grid_dim64, %grid_dim;

    // global thread index
    mad.lo.u64   %global_id, %bid64, %bdim64, %tid64;

    // total number of threads in the launch
    mul.lo.u64   %total_threads, %grid_dim64, %bdim64;

    // load kernel arguments
    ld.param.u64 %input_ptr, [input_ptr];
    ld.param.u64 %output_ptr, [output_ptr];
    ld.param.u64 %N,         [N];

    // start index for this thread
    mov.u64      %i, %global_id;

    // if first index already out of bounds, skip everything
    setp.ge.u64  %p, %i, %N;
    @%p bra      DONE;

LOOP:
    // byte offset = i * sizeof(fp16) = i * 2
    mul.wide.u64 %offset, %i, 2;
    add.u64      %addr_in, %input_ptr, %offset;
    ld.global.u16 %x_h, [%addr_in];
    cvt.f32.f16  %x_f, %x_h;

    // sigmoid = 1 / (1 + exp(-x))
    mov.f32      %x_orig, %x_f;
    neg.f32      %neg_x, %x_orig;
    exp.approx.f32 %exp_val, %neg_x;
    add.f32      %denom, %exp_val, 1.0;
    rcp.approx.f32 %sig_f, %denom;

    // y = x * sigmoid(x)
    mul.f32      %y_f, %x_orig, %sig_f;

    // store result as fp16
    cvt.f16.f32  %y_h, %y_f;
    add.u64      %addr_out, %output_ptr, %offset;
    st.global.u16 [%addr_out], %y_h;

    // advance to next element handled by this thread
    add.u64      %i, %i, %total_threads;
    setp.lt.u64  %p, %i, %N;
    @%p bra      LOOP;

DONE:
    ret;
}
"""

# ----------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel.
# The harness is assumed to provide `ptx_load` and `ptx_launch`.
# ----------------------------------------------------------------------
import torch
import torch.nn as nn

class ModelNew:
    def __init__(self):
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        """
        Apply Swish activation using the custom PTX kernel.
        Expected: x is a CUDA tensor of dtype torch.float16.
        """
        if not x.is_cuda:
            raise RuntimeError("Input tensor must be on CUDA device")
        if x.dtype != torch.float16:
            raise RuntimeError("Input tensor must be float16 (fp16)")

        out = torch.empty_like(x)

        # total number of elements
        N = x.numel()

        # launch configuration (256 threads per block)
        threads_per_block = 256
        blocks = (N + threads_per_block - 1) // threads_per_block
        grid = (blocks, 1, 1)
        block = (threads_per_block, 1, 1)

        # arguments: input ptr, output ptr, size (as 64‑bit integer)
        args = [x.data_ptr(), out.data_ptr(), N]

        # launch the kernel
        ptx_launch(self.module, "swish_kernel", grid, block, args)

        return out
